package seed

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"testing"
)

// The suite-v1 --small fixtures: what seed all would write to data/out,
// generated by posting each planted books view to the fake ERPNext of
// books_test.go, and the ground truth seed plant builds from them.
const (
	mapsV1Dir  = "testdata/maps-v1"
	truthV1Dir = "testdata/ground_truth-v1"
)

func checkV1Golden(t *testing.T, path string, got []byte) {
	t.Helper()
	if *update {
		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, got, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	want, err := os.ReadFile(path) //nolint:gosec // G304: repo testdata
	if err != nil {
		t.Fatalf("read golden (run go test ./internal/seed -run 'TestMapsV1Fixtures|TestGroundTruthSuiteV1' -update): %v", err)
	}
	if !bytes.Equal(got, want) {
		t.Errorf("output differs from %s; run go test ./internal/seed -run 'TestMapsV1Fixtures|TestGroundTruthSuiteV1' -update and review the diff", path)
	}
}

// TestMapsV1Fixtures posts every seeded month of suite-v1 (--small), in
// order, to one fake ERPNext per company, as seed all does, and checks the
// bootstrap reports and the evaluated months' ERP maps against
// testdata/maps-v1. It also proves the fake books accept every planted
// document, the unallocated advances included.
func TestMapsV1Fixtures(t *testing.T) {
	cfg := loadSuiteV1(t)
	cfg.Small = true
	profiles := suiteProfiles(t)
	sp := NewSuitePlanter(cfg, profiles, Options{Small: true})
	evaluated := map[CompanyMonth]bool{}
	for _, cm := range cfg.EvaluatedMonths() {
		evaluated[cm] = true
	}
	for _, c := range []string{"mehta", "sharma"} {
		p := profiles[c]
		rep, err := Bootstrap(context.Background(), newSiteFake(p).client(t), p)
		if err != nil {
			t.Fatalf("bootstrap %s: %v", c, err)
		}
		b, err := BootstrapReportJSON(rep)
		if err != nil {
			t.Fatal(err)
		}
		path, err := BootstrapReportPath(mapsV1Dir, cfg.Suite, c)
		if err != nil {
			t.Fatal(err)
		}
		checkV1Golden(t, path, b)

		f := newFakeBooks(rep)
		for _, m := range cfg.SeededMonths(c) {
			pw := mustPlant(t, sp, c, m)
			res := writeBooks(t, f, rep, pw.BooksWorld, BooksOptions{Suppliers: p.Suppliers})
			if !evaluated[CompanyMonth{c, m}] {
				continue
			}
			mj, err := res.Map.JSON()
			if err != nil {
				t.Fatal(err)
			}
			dir, err := ERPMapDir(mapsV1Dir, cfg.Suite, c, m)
			if err != nil {
				t.Fatal(err)
			}
			checkV1Golden(t, filepath.Join(dir, ERPMapFile), mj)
		}
	}
}

// v1Truth builds a target's ground truth from the maps-v1 fixtures, as
// seed plant --maps internal/seed/testdata/maps-v1 does.
type v1Truth struct {
	gt    GroundTruth
	lines []BankLine
	g2b   GSTR2B
	erp   ERPMap
	names map[string]string
	pw    PlantedWorld
}

func buildV1Truth(t *testing.T, sp *SuitePlanter, cfg ScenarioConfig, cm CompanyMonth) v1Truth {
	t.Helper()
	pw := mustPlant(t, sp, cm.Company, cm.Month)
	lines, err := BankLines(pw.BankWorld)
	if err != nil {
		t.Fatal(err)
	}
	g := suiteGSTR2B(t, sp, cm.Company, cm.Month)
	var erp ERPMap
	if !pw.Clean {
		dir, err := ERPMapDir(mapsV1Dir, cfg.Suite, cm.Company, cm.Month)
		if err != nil {
			t.Fatal(err)
		}
		if erp, err = LoadERPMap(filepath.Join(dir, ERPMapFile)); err != nil {
			t.Fatal(err)
		}
	}
	path, err := BootstrapReportPath(mapsV1Dir, cfg.Suite, cm.Company)
	if err != nil {
		t.Fatal(err)
	}
	rep, err := LoadBootstrapReport(path)
	if err != nil {
		t.Fatal(err)
	}
	names := SupplierNames(sp.profiles[cm.Company], &rep)
	gt, err := BuildGroundTruth(GroundTruthOptions{PlantedWorld: pw, BankLines: lines, ERPMap: erp, GSTR2B: &g, Suppliers: names})
	if err != nil {
		t.Fatalf("BuildGroundTruth %v: %v", cm, err)
	}
	return v1Truth{gt: gt, lines: lines, g2b: g, erp: erp, names: names, pw: pw}
}

func TestSupplierNames(t *testing.T) {
	p := loadCompany(t, "mehta")
	byProfile := SupplierNames(p, nil)
	if byProfile["lotus-business-parks"] != "Lotus Business Parks" {
		t.Errorf("profile fallback %v", byProfile)
	}
	rep := BootstrapReport{Suppliers: map[string]string{"lotus-business-parks": "Lotus Business Parks (2)"}}
	if got := SupplierNames(p, &rep)["lotus-business-parks"]; got != "Lotus Business Parks (2)" {
		t.Errorf("report name %q", got)
	}
	if _, err := BootstrapReportPath("x", "../suite", "mehta"); err == nil {
		t.Error("a path in the suite was accepted")
	}
}
